class Solution {
    public long bestWeek(int[] sales, int k) {
        long best = Long.MIN_VALUE;
        for (int i = 0; i + k <= sales.length; i++) {
            long total = 0;
            for (int j = i; j < i + k; j++) total += sales[j];
            best = Math.max(best, total);
        }
        return best;
    }
}

